package org.evox.spen.compat;
import android.bluetooth.BluetoothAdapter;
/** The port uses active AOSP Bluetooth; Samsung radio-only power mode is unavailable. */
public final class BluetoothAccess {
 public static android.bluetooth.le.ScanSettings.Builder customScanParams(android.bluetooth.le.ScanSettings.Builder builder,int interval,int window){android.util.Log.i("AirCommandPort","Use AOSP low-latency scan timing; Samsung custom scan intervals unavailable");return builder;}
 public static android.bluetooth.le.ScanSettings.Builder scanMode(android.bluetooth.le.ScanSettings.Builder builder,int mode){return builder.setScanMode(mode==100?android.bluetooth.le.ScanSettings.SCAN_MODE_LOW_LATENCY:mode);}
 public static android.bluetooth.BluetoothGatt connect(android.bluetooth.BluetoothDevice device,android.content.Context context,boolean auto,int transport,int phy,android.os.ParcelUuid uuid,android.os.Handler handler,android.bluetooth.BluetoothGattCallback callback){boolean direct=canConnectPaired(context,device.getAddress());android.util.Log.i("AirCommandPort","Native pen GATT request: verifiedPaired="+direct+", originalAuto="+auto);return device.connectGatt(context,auto,callback,transport,phy,handler);}
 public static boolean canConnectPaired(android.content.Context context,String address){
  try{if(context==null||!canScan(context))return false;BluetoothAdapter adapter=((android.bluetooth.BluetoothManager)context.getSystemService(android.content.Context.BLUETOOTH_SERVICE)).getAdapter();if(adapter==null||!adapter.isEnabled())return false;String nativeAddress=new NativeSpenHardware().getBleSpenAddress();if(address!=null&&!nativeAddress.equalsIgnoreCase(address))return false;return adapter.getRemoteDevice(nativeAddress).getBondState()==android.bluetooth.BluetoothDevice.BOND_BONDED;}catch(Exception e){android.util.Log.w("AirCommandPort","Native paired pen check unavailable: "+e.getClass().getSimpleName());return false;}
 }
 public static boolean canReconnectDetached(android.content.Context context){return canConnectPaired(context,null);}
 public static boolean canConnectDetachedPaired(android.content.Context context,String address){try{return !new NativeSpenHardware().isSpenInserted()&&canConnectPaired(context,address);}catch(Exception unavailable){return false;}}
 public static boolean canConnectKnown(android.content.Context context,String address){try{if(!canScan(context)||!BluetoothAdapter.checkBluetoothAddress(address))return false;String saved=new NativeSpenHardware().getBleSpenAddress();if(!saved.equalsIgnoreCase(address))return false;android.util.Log.i("AirCommandPort","Discovery timed out; original connector will try verified Samsung EFS address directly");return true;}catch(Exception e){android.util.Log.w("AirCommandPort","Known pen connection unavailable: "+e.getMessage());return false;}}
 public static boolean canScan(android.content.Context context){return context.checkSelfPermission("android.permission.BLUETOOTH_SCAN")==android.content.pm.PackageManager.PERMISSION_GRANTED&&context.checkSelfPermission("android.permission.BLUETOOTH_CONNECT")==android.content.pm.PackageManager.PERMISSION_GRANTED;}
 public static boolean isBleEnabled(BluetoothAdapter adapter){return adapter!=null&&adapter.isEnabled();}
 public static boolean setStandaloneBleMode(BluetoothAdapter adapter,boolean requested){return standAlone(adapter,requested);}
 public static boolean standAlone(BluetoothAdapter adapter,boolean requested){boolean ready=adapter!=null&&adapter.isEnabled();android.util.Log.i("AirCommandPort","Samsung BLE mode request="+requested+"; AOSP Bluetooth active="+ready);return ready;}

 public static String alias(android.bluetooth.BluetoothDevice d){return d.getAlias();}
 public static boolean alias(android.bluetooth.BluetoothDevice d,String alias){return d.setAlias(alias)==0;}
 public static boolean removeBond(android.bluetooth.BluetoothDevice d){try{Object h=NativeSpenHardware.obtain(RuntimeContext.app(),"spengestureservice");if(!(h instanceof NativeSpenHardware)||!d.getAddress().equalsIgnoreCase(((NativeSpenHardware)h).getBleSpenAddress())){android.util.Log.w("AirCommandPort","Bond reset restricted to verified native pen");return false;}String apk=RuntimeContext.app().getApplicationInfo().sourceDir;return "OK".equals(RootAccess.run("CLASSPATH="+RootAccess.quote(apk)+" app_process /system/bin org.evox.spen.compat.RootBluetoothMain "+RootAccess.quote(d.getAddress())).trim());}catch(Exception failure){android.util.Log.w("AirCommandPort","Original pen bond reset failed: "+failure.getClass().getSimpleName());return false;}}
}
